import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import {
  Building,
  User,
  HeartPulse,
  Shield,
  Users,
  Syringe,
} from "lucide-react";

const RoleSelectionPage = () => {
  const [selectedRole, setSelectedRole] = useState("");
  const navigate = useNavigate();

  const roles = [
    {
      id: "hospital",
      title: "Hospital / Blood Bank",
      description:
        "Manage blood inventory, handle requests, and coordinate with donors",
      icon: <Building className="w-12 h-12" />,
      color: "from-blue-500 to-blue-700",
      gradient: "bg-gradient-to-r from-blue-500 to-blue-700",
    },
    {
      id: "donor",
      title: "Blood Donor",
      description:
        "Donate blood, manage availability, and respond to emergency requests",
      icon: <Syringe className="w-12 h-12" />,
      color: "from-green-500 to-green-700",
      gradient: "bg-gradient-to-r from-green-500 to-green-700",
    },
    {
      id: "patient",
      title: "Patient / Emergency User",
      description:
        "Request blood donations and connect with nearby hospitals/donors",
      icon: <HeartPulse className="w-12 h-12" />,
      color: "from-red-500 to-red-700",
      gradient: "bg-gradient-to-r from-red-500 to-red-700",
    },
  ];

  const handleRoleSelect = (roleId) => {
    setSelectedRole(roleId);
  };

  const handleContinue = () => {
    if (selectedRole) {
      // Navigate to the appropriate dashboard based on selected role
      switch (selectedRole) {
        case "hospital":
          navigate("/hospital-dashboard");
          break;
        case "donor":
          navigate("/donor-dashboard");
          break;
        case "patient":
          navigate("/patient-dashboard");
          break;
        default:
          navigate("/");
      }
    }
  };

  const containerVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        staggerChildren: 0.2,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.5 },
    },
  };

  const cardVariants = {
    rest: {
      scale: 1,
      rotateX: 0,
      boxShadow: "0 8px 32px rgba(0, 0, 0, 0.1)",
    },
    hover: {
      scale: 1.05,
      rotateX: -5,
      boxShadow: "0 20px 60px rgba(0, 0, 0, 0.3)",
      transition: {
        type: "spring",
        stiffness: 300,
        damping: 15,
      },
    },
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-red-900 flex items-center justify-center p-4">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="w-full max-w-4xl mx-auto"
      >
        {/* Header */}
        <motion.div variants={itemVariants} className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold text-white mb-4">
            Who are you?
          </h1>
          <p className="text-xl text-gray-300 max-w-2xl mx-auto">
            Select your role to access the appropriate dashboard and features
          </p>
        </motion.div>

        {/* Role Cards */}
        <motion.div
          variants={itemVariants}
          className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-12"
        >
          {roles.map((role, index) => (
            <motion.div
              key={role.id}
              variants={cardVariants}
              whileHover="hover"
              animate={selectedRole === role.id ? "hover" : "rest"}
              className={`cursor-pointer glass-card p-8 rounded-3xl text-center transition-all duration-300 ${
                selectedRole === role.id
                  ? "ring-2 ring-white ring-opacity-50 bg-white/15"
                  : "hover:bg-white/10"
              }`}
              onClick={() => handleRoleSelect(role.id)}
            >
              <motion.div
                animate={{
                  scale: selectedRole === role.id ? 1.1 : 1,
                  rotateY: selectedRole === role.id ? 360 : 0,
                }}
                transition={{ duration: 0.3 }}
                className={`mx-auto mb-6 p-4 rounded-full ${role.gradient} bg-opacity-20`}
              >
                <div
                  className={`${
                    selectedRole === role.id ? "text-white" : "text-red-400"
                  }`}
                >
                  {role.icon}
                </div>
              </motion.div>

              <h3 className="text-2xl font-bold text-white mb-3">
                {role.title}
              </h3>
              <p className="text-gray-300 mb-6">{role.description}</p>

              <motion.div
                animate={{
                  scale: selectedRole === role.id ? 1 : 0,
                }}
                className="flex justify-center"
              >
                <div className="w-6 h-6 rounded-full bg-white"></div>
              </motion.div>
            </motion.div>
          ))}
        </motion.div>

        {/* Continue Button */}
        <motion.div variants={itemVariants} className="text-center">
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={handleContinue}
            disabled={!selectedRole}
            className={`px-12 py-4 rounded-xl font-bold text-lg transition-all duration-300 ${
              selectedRole
                ? "bg-gradient-to-r from-red-500 to-red-700 text-white shadow-lg hover:shadow-xl transform hover:scale-105"
                : "bg-gray-700 text-gray-400 cursor-not-allowed"
            }`}
          >
            Continue to Dashboard
          </motion.button>
        </motion.div>

        {/* Skip Option */}
        <motion.div variants={itemVariants} className="mt-8 text-center">
          <button
            onClick={() => navigate("/")}
            className="text-gray-400 hover:text-white transition-colors"
          >
            Skip and explore as guest
          </button>
        </motion.div>

        {/* Navigation */}
        <motion.div variants={itemVariants} className="mt-12 text-center">
          <Link
            to="/auth"
            className="text-gray-400 hover:text-white transition-colors inline-flex items-center"
          >
            ← Back to Sign In
          </Link>
        </motion.div>
      </motion.div>
    </div>
  );
};

export default RoleSelectionPage;
